"use client";

import React, { useState } from "react";
import { DollarSign, ArrowRight } from "lucide-react";

export function BillingCreditBalanceCard() {
  const [amount, setAmount] = useState(120.45);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5">
          <DollarSign className="w-4 h-4 text-emerald-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Credit Balance</span>
        </div>
        <span className="text-[9px] uppercase font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20">Active</span>
      </div>

      <div className="space-y-4">
        <div className="p-4 rounded-xl bg-white/[0.02] border border-white/[0.03] relative overflow-hidden">
          <span className="block text-[9px] text-muted-foreground/60 uppercase font-bold">Remaining Credit</span>
          <span className="text-2xl font-black text-foreground">${amount.toFixed(2)}</span>
        </div>

        <button 
          onClick={() => setAmount(amount + 50.00)}
          className="w-full py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-1.5 transition-all"
        >
          <span>Top Up (+$50.00)</span>
          <ArrowRight className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  );
}
